<?php

namespace App\Controllers;

use App\Core\Auth;
use App\Core\Database;
use App\Core\RateLimiter;
use App\Core\Request;
use App\Core\Security;
use App\Core\Session;
use App\Core\Setting;
use App\Core\Validator;
use App\Models\AuditLog;
use App\Models\User;
use App\Services\AuditService;
use App\Services\DemoService;
use App\Services\DeveloperDataService;

/**
 * Unlinked developer console.
 *
 * The only credential is the high-entropy developer key embedded in the URL.
 * It is generated by the installer and stored in config/local.php. There is
 * deliberately no navigation link, login form, or discovery endpoint.
 *
 * The console sits outside the user RBAC model: it can inspect every table,
 * create or repair accounts, change settings, run guarded SQL, and manage the
 * synthetic demonstration dataset. Every action is audited.
 */
final class DeveloperController extends BaseController
{
    private DeveloperDataService $data;
    private User $users;

    public function __construct()
    {
        $this->data = new DeveloperDataService();
        $this->users = new User();
    }

    /* ---------------------------------------------------------------------
     * Dashboard
     * ------------------------------------------------------------------ */

    public function index(string $key): void
    {
        $this->guard($key);
        $stats = $this->data->databaseStats();

        $roleCounts = Database::fetchAll(
            'SELECT r.slug, r.name,
                    COUNT(u.id) AS total,
                    SUM(CASE WHEN u.is_demo = 1 THEN 1 ELSE 0 END) AS demo_count,
                    SUM(CASE WHEN u.is_demo = 0 THEN 1 ELSE 0 END) AS live_count
             FROM roles r
             LEFT JOIN users u ON u.role_id = r.id
             GROUP BY r.id, r.slug, r.name
             ORDER BY r.id ASC'
        );
        foreach ($roleCounts as &$row) {
            $row['total'] = (int) $row['total'];
            $row['demo_count'] = (int) $row['demo_count'];
            $row['live_count'] = (int) $row['live_count'];
        }
        unset($row);

        $recentUsers = Database::fetchAll(
            'SELECT u.id, u.username, u.first_name, u.last_name, u.email, u.status, u.is_demo, u.created_at,
                    r.slug AS role, r.name AS role_name
             FROM users u JOIN roles r ON r.id = u.role_id
             ORDER BY u.id DESC LIMIT 8'
        );
        $recentAudit = (new AuditLog())->paginate([], 1, 8)['rows'];

        $this->view('developer/index', [
            'pageTitle' => 'Developer dashboard',
            'developerKey' => $key,
            'stats' => $stats,
            'roleCounts' => $roleCounts,
            'recentUsers' => $recentUsers,
            'recentAudit' => $recentAudit,
            'auditToday' => (int) Database::scalar(
                'SELECT COUNT(*) FROM audit_logs WHERE created_at >= CURDATE()',
                [],
                0
            ),
            'activeSessions' => (int) Database::scalar(
                'SELECT COUNT(*) FROM user_sessions WHERE last_activity > (NOW() - INTERVAL 30 MINUTE)',
                [],
                0
            ),
            'demoMode' => Setting::demoMode(),
            'appVersion' => (string) config('app.version', '—'),
            'phpVersion' => PHP_VERSION,
            'health' => $this->healthChecks($key),
        ], 'layouts/developer');
    }

    /* ---------------------------------------------------------------------
     * User management
     * ------------------------------------------------------------------ */

    public function users(string $key): void
    {
        $this->guard($key);

        $filters = [
            'search' => $this->input('search', ''),
            'role' => $this->input('role', ''),
            'status' => $this->input('status', ''),
        ];
        $scope = $this->input('is_demo', '');
        if ($scope !== '') {
            $filters['is_demo'] = (int) $scope;
        }

        $pagination = $this->users->paginate($filters, $this->page(), 25);

        $this->view('developer/users', [
            'pageTitle' => 'Users',
            'developerKey' => $key,
            'pagination' => $pagination,
            'filters' => $filters,
            'roles' => Database::fetchAll('SELECT id, slug, name FROM roles ORDER BY id'),
            'roleCounts' => $this->userRoleCounts(),
            'demoMode' => Setting::demoMode(),
        ], 'layouts/developer');
    }

    public function createUser(string $key): void
    {
        $this->guard($key);
        $this->view('developer/user-form', array_merge($this->userFormData(null), [
            'developerKey' => $key,
            'generatedCredentials' => null,
        ]), 'layouts/developer');
    }

    public function storeUser(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        if (RateLimiter::tooMany('developer.user_write', 60, 3600)) {
            $this->error('Too many developer account changes from this network. Try again later.', $this->console($key, 'users'));
        }

        $payload = $this->userPayload();
        $validator = Validator::make($payload + [
            'password_mode' => $this->postString('password_mode', 'generate'),
        ], [
            'first_name' => 'required|max:80',
            'middle_name' => 'nullable|max:80',
            'last_name' => 'required|max:80',
            'suffix' => 'nullable|max:20',
            'username' => 'required|min:3|max:80|regex:/^[A-Za-z0-9._-]+$/',
            'email' => 'required|email|max:190',
            'employee_number' => 'nullable|max:40',
            'student_number' => 'nullable|max:40',
            'phone' => 'nullable|max:30',
            'role' => 'required|in:dean,academic_head,instructor,student',
            'status' => 'required|in:active,inactive',
            'password_mode' => 'required|in:generate,manual',
        ]);

        if ($validator->fails()) {
            $this->rememberUserInput($payload);
            $this->error((string) $validator->firstError(), $this->console($key, 'users/create'));
        }

        $roleId = $this->users->roleId($payload['role']);
        if ($roleId === null) {
            $this->rememberUserInput($payload);
            $this->error('That role is not available in this installation.', $this->console($key, 'users/create'));
        }

        if ($this->userValueExists('username', $payload['username']) || $this->userValueExists('email', $payload['email'])) {
            $this->rememberUserInput($payload);
            $this->error('That username or email address is already registered.', $this->console($key, 'users/create'));
        }
        foreach (['employee_number', 'student_number'] as $column) {
            if ($payload[$column] !== '' && $this->userValueExists($column, $payload[$column])) {
                $this->rememberUserInput($payload);
                $this->error('That ' . str_replace('_', ' ', $column) . ' is already registered.', $this->console($key, 'users/create'));
            }
        }

        $mode = $this->postString('password_mode', 'generate');
        $generated = $mode === 'generate';
        if ($generated) {
            $plainPassword = Security::temporaryPassword();
            $mustChange = 1;
        } else {
            $plainPassword = (string) $this->input('password', '');
            $problem = Security::passwordProblem($plainPassword);
            if ($problem !== null) {
                $this->rememberUserInput($payload);
                $this->error($problem, $this->console($key, 'users/create'));
            }
            if ($plainPassword !== (string) $this->input('password_confirmation', '')) {
                $this->rememberUserInput($payload);
                $this->error('The password confirmation does not match.', $this->console($key, 'users/create'));
            }
            $mustChange = $this->input('must_change_password') ? 1 : 0;
        }

        try {
            $id = Database::transaction(function () use ($payload, $roleId, $plainPassword, $mustChange): int {
                return $this->users->createAccount([
                    'role_id' => $roleId,
                    'username' => $payload['username'],
                    'email' => $payload['email'],
                    'password_hash' => password_hash($plainPassword, PASSWORD_DEFAULT),
                    'first_name' => $payload['first_name'],
                    'middle_name' => $payload['middle_name'] !== '' ? $payload['middle_name'] : null,
                    'last_name' => $payload['last_name'],
                    'suffix' => $payload['suffix'] !== '' ? $payload['suffix'] : null,
                    'employee_number' => $payload['employee_number'] !== '' ? $payload['employee_number'] : null,
                    'student_number' => $payload['student_number'] !== '' ? $payload['student_number'] : null,
                    'department_id' => (int) $this->input('department_id', 0) ?: null,
                    'program_id' => (int) $this->input('program_id', 0) ?: null,
                    'section_id' => (int) $this->input('section_id', 0) ?: null,
                    'year_level' => (int) $this->input('year_level', 0) ?: null,
                    'phone' => $payload['phone'] !== '' ? $payload['phone'] : null,
                    'status' => $payload['status'],
                    'is_demo' => $this->input('is_demo') ? 1 : 0,
                    'must_change_password' => $mustChange,
                ]);
            });
        } catch (\Throwable $e) {
            error_log('Developer user creation failed: ' . $e->getMessage());
            $this->rememberUserInput($payload);
            $this->error('The account could not be created: ' . $e->getMessage(), $this->console($key, 'users/create'));
        }

        Session::remove('_old');
        (new AuditService())->record(
            'developer.user_create',
            'user',
            $id,
            'Created ' . $payload['role'] . ' account ' . $payload['username']
            . ($generated ? ' with a generated temporary password' : ' with an explicit password')
        );

        if ($generated) {
            Session::set('_developer_credentials', [
                'user_id' => $id,
                'username' => $payload['username'],
                'password' => $plainPassword,
                'kind' => 'temporary',
            ]);
        }
        $this->success('Account created.', $this->console($key, 'users/' . $id . '/edit'));
    }

    public function editUser(string $key, string $id): void
    {
        $this->guard($key);
        $user = $this->users->findWithRelations((int) $id);
        if (!$user) {
            abort(404);
        }

        $generated = Session::pull('_developer_credentials');
        if (!is_array($generated) || (int) ($generated['user_id'] ?? 0) !== (int) $id) {
            $generated = null;
        }

        $this->view('developer/user-form', array_merge($this->userFormData($user), [
            'developerKey' => $key,
            'generatedCredentials' => $generated,
        ]), 'layouts/developer');
    }

    public function updateUser(string $key, string $id): void
    {
        $this->guard($key);
        $this->requirePost();
        $id = (int) $id;
        $user = $this->users->findWithRelations($id);
        if (!$user) {
            abort(404);
        }

        $payload = $this->userPayload();
        $validator = Validator::make($payload, [
            'first_name' => 'required|max:80',
            'middle_name' => 'nullable|max:80',
            'last_name' => 'required|max:80',
            'suffix' => 'nullable|max:20',
            'username' => 'required|min:3|max:80|regex:/^[A-Za-z0-9._-]+$/',
            'email' => 'required|email|max:190',
            'employee_number' => 'nullable|max:40',
            'student_number' => 'nullable|max:40',
            'phone' => 'nullable|max:30',
            'role' => 'required|in:dean,academic_head,instructor,student',
            'status' => 'required|in:active,inactive',
        ]);
        if ($validator->fails()) {
            $this->rememberUserInput($payload);
            $this->error((string) $validator->firstError(), $this->console($key, 'users/' . $id . '/edit'));
        }

        $roleId = $this->users->roleId($payload['role']);
        if ($roleId === null) {
            $this->rememberUserInput($payload);
            $this->error('That role is not available in this installation.', $this->console($key, 'users/' . $id . '/edit'));
        }

        if ($this->userValueExists('username', $payload['username'], $id) || $this->userValueExists('email', $payload['email'], $id)) {
            $this->rememberUserInput($payload);
            $this->error('That username or email address belongs to another account.', $this->console($key, 'users/' . $id . '/edit'));
        }
        foreach (['employee_number', 'student_number'] as $column) {
            if ($payload[$column] !== '' && $this->userValueExists($column, $payload[$column], $id)) {
                $this->rememberUserInput($payload);
                $this->error('That ' . str_replace('_', ' ', $column) . ' belongs to another account.', $this->console($key, 'users/' . $id . '/edit'));
            }
        }

        if ((string) $user['role'] === 'dean'
            && ($payload['role'] !== 'dean' || $payload['status'] !== 'active')
            && $this->activeDeans() <= 1
        ) {
            $this->rememberUserInput($payload);
            $this->error('At least one active Dean account must remain.', $this->console($key, 'users/' . $id . '/edit'));
        }

        $this->users->updateAccount($id, [
            'role_id' => $roleId,
            'username' => $payload['username'],
            'email' => $payload['email'],
            'first_name' => $payload['first_name'],
            'middle_name' => $payload['middle_name'] !== '' ? $payload['middle_name'] : null,
            'last_name' => $payload['last_name'],
            'suffix' => $payload['suffix'] !== '' ? $payload['suffix'] : null,
            'employee_number' => $payload['employee_number'] !== '' ? $payload['employee_number'] : null,
            'student_number' => $payload['student_number'] !== '' ? $payload['student_number'] : null,
            'department_id' => (int) $this->input('department_id', 0) ?: null,
            'program_id' => (int) $this->input('program_id', 0) ?: null,
            'section_id' => (int) $this->input('section_id', 0) ?: null,
            'year_level' => (int) $this->input('year_level', 0) ?: null,
            'phone' => $payload['phone'] !== '' ? $payload['phone'] : null,
            'status' => $payload['status'],
        ]);

        Session::remove('_old');
        (new AuditService())->record('developer.user_update', 'user', $id, 'Updated account ' . $payload['username']);
        $this->success('Account updated.', $this->console($key, 'users/' . $id . '/edit'));
    }

    public function toggleUserStatus(string $key, string $id): void
    {
        $this->guard($key);
        $this->requirePost();
        $id = (int) $id;
        $user = $this->users->findWithRelations($id);
        if (!$user) {
            abort(404);
        }
        if ((string) $user['role'] === 'dean' && (string) $user['status'] === 'active' && $this->activeDeans() <= 1) {
            $this->error('At least one active Dean account must remain.', $this->console($key, 'users'));
        }

        $new = (string) $user['status'] === 'active' ? 'inactive' : 'active';
        $this->users->setStatus($id, $new);
        (new AuditService())->record('developer.user_status', 'user', $id, 'Set account status to ' . $new);
        Database::execute('DELETE FROM user_sessions WHERE user_id = ?', [$id]);
        $this->success('Account marked ' . $new . '.', $this->console($key, 'users'));
    }

    public function resetUserPassword(string $key, string $id): void
    {
        $this->guard($key);
        $this->requirePost();
        $id = (int) $id;
        $user = $this->users->findWithRelations($id);
        if (!$user) {
            abort(404);
        }

        $generate = (bool) $this->input('generate');
        if ($generate) {
            $plain = Security::temporaryPassword();
            $mustChange = true;
        } else {
            $plain = (string) $this->input('password', '');
            $problem = Security::passwordProblem($plain);
            if ($problem !== null) {
                $this->error($problem, $this->console($key, 'users/' . $id . '/edit'));
            }
            if ($plain !== (string) $this->input('password_confirmation', '')) {
                $this->error('The password confirmation does not match.', $this->console($key, 'users/' . $id . '/edit'));
            }
            $mustChange = (bool) $this->input('must_change_password');
        }

        $this->users->resetPassword($id, $plain, $mustChange);
        (new AuditService())->record(
            'developer.user_password',
            'user',
            $id,
            'Reset the account password' . ($mustChange ? '; a change is required at next sign-in' : '')
        );

        if ($generate) {
            Session::set('_developer_credentials', [
                'user_id' => $id,
                'username' => $user['username'],
                'password' => $plain,
                'kind' => 'temporary',
            ]);
        }
        $this->success(
            $generate ? 'Temporary password generated and all existing sessions signed out.' : 'Password reset and all existing sessions signed out.',
            $this->console($key, 'users/' . $id . '/edit')
        );
    }

    public function deleteUser(string $key, string $id): void
    {
        $this->guard($key);
        $this->requirePost();
        $id = (int) $id;
        $user = $this->users->findWithRelations($id);
        if (!$user) {
            abort(404);
        }
        if ((string) $user['role'] === 'dean' && (string) $user['status'] === 'active' && $this->activeDeans() <= 1) {
            $this->error('At least one active Dean account must remain.', $this->console($key, 'users/' . $id . '/edit'));
        }

        try {
            Database::execute('DELETE FROM users WHERE id = ?', [$id]);
        } catch (\Throwable $e) {
            error_log('Developer user deletion failed: ' . $e->getMessage());
            $this->error('The account could not be deleted: ' . $e->getMessage(), $this->console($key, 'users/' . $id . '/edit'));
        }

        (new AuditService())->record('developer.user_delete', 'user', $id, 'Deleted account ' . $user['username']);
        $this->success('Account deleted.', $this->console($key, 'users'));
    }

    /* ---------------------------------------------------------------------
     * Generic data browser
     * ------------------------------------------------------------------ */

    public function data(string $key): void
    {
        $this->guard($key);
        $this->view('developer/data', [
            'pageTitle' => 'Data browser',
            'developerKey' => $key,
            'tables' => $this->data->tables(),
            'stats' => $this->data->databaseStats(),
        ], 'layouts/developer');
    }

    public function dataTable(string $key, string $table): void
    {
        $this->guard($key);
        if (!$this->data->tableExists($table)) {
            abort(404);
        }

        $search = (string) $this->input('search', '');
        $pagination = $this->data->paginate($table, $this->page(), 25, $search);
        $this->view('developer/rows', [
            'pageTitle' => $table,
            'developerKey' => $key,
            'table' => $table,
            'columns' => $this->data->columns($table),
            'pagination' => $pagination,
            'search' => $search,
            'primaryKey' => $this->data->primaryKey($table),
            'compositePrimaryKey' => $this->data->hasCompositePrimaryKey($table),
        ], 'layouts/developer');
    }

    public function createRow(string $key, string $table): void
    {
        $this->guard($key);
        if (!$this->data->tableExists($table)) {
            abort(404);
        }
        $this->view('developer/row-form', [
            'pageTitle' => 'New row · ' . $table,
            'developerKey' => $key,
            'table' => $table,
            'row' => null,
            'columns' => $this->data->columns($table),
            'foreignOptions' => $this->foreignOptions($table),
            'primaryKey' => $this->data->primaryKey($table),
        ], 'layouts/developer');
    }

    public function storeRow(string $key, string $table): void
    {
        $this->guard($key);
        $this->requirePost();
        if (!$this->data->tableExists($table)) {
            abort(404);
        }

        $fields = $this->postArray('fields');
        $result = $this->data->create($table, $fields);
        if (!$result['ok']) {
            Session::set('_old', ['fields' => $fields]);
            $this->error('Row could not be created: ' . $result['error'], $this->console($key, 'data/' . rawurlencode($table) . '/create'));
        }

        (new AuditService())->record('developer.data_create', $table, (int) ($result['id'] ?? 0), 'Inserted a row into ' . $table);
        $this->success('Row created in ' . $table . '.', $this->console($key, 'data/' . rawurlencode($table)));
    }

    public function editRow(string $key, string $table, string $id): void
    {
        $this->guard($key);
        if (!$this->data->tableExists($table)) {
            abort(404);
        }
        $row = $this->data->find($table, $id);
        if (!$row) {
            abort(404);
        }
        $this->view('developer/row-form', [
            'pageTitle' => 'Edit row · ' . $table,
            'developerKey' => $key,
            'table' => $table,
            'row' => $row,
            'columns' => $this->data->columns($table),
            'foreignOptions' => $this->foreignOptions($table),
            'primaryKey' => $this->data->primaryKey($table),
        ], 'layouts/developer');
    }

    public function updateRow(string $key, string $table, string $id): void
    {
        $this->guard($key);
        $this->requirePost();
        if (!$this->data->tableExists($table)) {
            abort(404);
        }

        $fields = $this->postArray('fields');
        $result = $this->data->update($table, $id, $fields);
        if (!$result['ok']) {
            Session::set('_old', ['fields' => $fields]);
            $this->error('Row could not be updated: ' . $result['error'], $this->console($key, 'data/' . rawurlencode($table) . '/' . rawurlencode($id) . '/edit'));
        }

        (new AuditService())->record('developer.data_update', $table, (int) $id, 'Updated a row in ' . $table);
        $this->success('Row updated in ' . $table . '.', $this->console($key, 'data/' . rawurlencode($table)));
    }

    public function deleteRow(string $key, string $table, string $id): void
    {
        $this->guard($key);
        $this->requirePost();
        if (!$this->data->tableExists($table)) {
            abort(404);
        }

        $result = $this->data->delete($table, $id);
        if (!$result['ok']) {
            $this->error('Row could not be deleted: ' . $result['error'], $this->console($key, 'data/' . rawurlencode($table)));
        }

        (new AuditService())->record('developer.data_delete', $table, (int) $id, 'Deleted a row from ' . $table);
        $this->success('Row deleted from ' . $table . '.', $this->console($key, 'data/' . rawurlencode($table)));
    }

    /* ---------------------------------------------------------------------
     * Settings
     * ------------------------------------------------------------------ */

    public function settings(string $key): void
    {
        $this->guard($key);
        $settings = Database::fetchAll(
            'SELECT s.*, u.username AS updated_by_username
             FROM system_settings s
             LEFT JOIN users u ON u.id = s.updated_by
             ORDER BY s.setting_group ASC, s.setting_key ASC'
        );
        $grouped = [];
        foreach ($settings as $setting) {
            $grouped[(string) $setting['setting_group']][] = $setting;
        }

        $this->view('developer/settings', [
            'pageTitle' => 'System settings',
            'developerKey' => $key,
            'settings' => $settings,
            'grouped' => $grouped,
            'demoMode' => Setting::demoMode(),
        ], 'layouts/developer');
    }

    public function updateSettings(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        $rows = Database::fetchAll('SELECT id, setting_key, setting_group FROM system_settings');
        $byId = [];
        foreach ($rows as $row) {
            $byId[(int) $row['id']] = $row;
        }

        $submitted = $this->postArray('settings');
        $updated = 0;
        foreach ($submitted as $id => $value) {
            $row = $byId[(int) $id] ?? null;
            if (!$row || is_array($value)) {
                continue;
            }
            $value = trim((string) $value);
            if (mb_strlen($value) > 5000) {
                $this->error('The value for ' . $row['setting_key'] . ' is too long.', $this->console($key, 'settings'));
            }
            Setting::set((string) $row['setting_key'], $value, (string) $row['setting_group']);
            $updated++;
        }

        Setting::clearCache();
        (new AuditService())->record('developer.settings_update', 'system_setting', null, 'Updated ' . $updated . ' system setting(s)');
        $this->success('Updated ' . $updated . ' setting(s).', $this->console($key, 'settings'));
    }

    public function storeSetting(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        $settingKey = strtolower($this->postString('setting_key'));
        $value = $this->postString('setting_value');
        $group = strtolower($this->postString('setting_group', 'general')) ?: 'general';

        if (!preg_match('/^[a-z0-9][a-z0-9_.-]{0,79}$/', $settingKey)) {
            $this->error('Setting keys must start with a letter or number and contain only lowercase letters, numbers, dots, dashes, and underscores.', $this->console($key, 'settings'));
        }
        if (!preg_match('/^[a-z0-9][a-z0-9_-]{0,39}$/', $group)) {
            $this->error('The group name contains invalid characters.', $this->console($key, 'settings'));
        }
        if ((int) Database::scalar('SELECT COUNT(*) FROM system_settings WHERE setting_key = ?', [$settingKey], 0) > 0) {
            $this->error('That setting key already exists. Edit it in the list above instead.', $this->console($key, 'settings'));
        }

        Setting::set($settingKey, $value, $group);
        Setting::clearCache();
        (new AuditService())->record('developer.setting_create', 'system_setting', null, 'Created setting ' . $settingKey);
        $this->success('Setting created.', $this->console($key, 'settings'));
    }

    public function deleteSetting(string $key, string $id): void
    {
        $this->guard($key);
        $this->requirePost();

        $row = Database::fetch('SELECT * FROM system_settings WHERE id = ?', [(int) $id]);
        if (!$row) {
            abort(404);
        }
        Database::execute('DELETE FROM system_settings WHERE id = ?', [(int) $id]);
        Setting::clearCache();
        (new AuditService())->record('developer.setting_delete', 'system_setting', (int) $id, 'Deleted setting ' . $row['setting_key']);
        $this->success('Setting deleted.', $this->console($key, 'settings'));
    }

    /* ---------------------------------------------------------------------
     * Audit log
     * ------------------------------------------------------------------ */

    public function auditLog(string $key): void
    {
        $this->guard($key);
        $filters = [
            'action' => $this->input('action', ''),
            'user_id' => $this->input('user_id', ''),
            'from' => $this->input('from', ''),
            'to' => $this->input('to', ''),
        ];
        $this->view('developer/audit', [
            'pageTitle' => 'Audit log',
            'developerKey' => $key,
            'pagination' => (new AuditLog())->paginate($filters, $this->page(), 40),
            'filters' => $filters,
            'users' => Database::fetchAll('SELECT id, first_name, last_name, username FROM users ORDER BY last_name, first_name'),
        ], 'layouts/developer');
    }

    /* ---------------------------------------------------------------------
     * SQL console
     * ------------------------------------------------------------------ */

    public function sql(string $key): void
    {
        $this->guard($key);
        $result = Session::pull('_developer_sql_result');
        $sqlText = Session::pull('_developer_sql_text');
        $this->view('developer/sql', [
            'pageTitle' => 'SQL console',
            'developerKey' => $key,
            'result' => is_array($result) ? $result : null,
            'sqlText' => is_string($sqlText) ? $sqlText : '',
            'tables' => $this->data->tables(),
        ], 'layouts/developer');
    }

    public function runSql(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        if (RateLimiter::tooMany('developer.sql', 120, 300)) {
            $this->error('Too many SQL statements from this network. Wait a few minutes and try again.', $this->console($key, 'sql'));
        }

        $sql = (string) $this->input('sql', '');
        $result = $this->data->executeSql(
            $sql,
            $this->postString('confirm'),
            $this->postString('confirm_text')
        );
        Session::set('_developer_sql_result', $result);
        Session::set('_developer_sql_text', $sql);

        (new AuditService())->record(
            'developer.sql_run',
            'database',
            null,
            substr('SQL ' . ($result['statement'] ?? '') . ': ' . preg_replace('/\s+/', ' ', $sql), 0, 480)
        );

        if (!$result['ok']) {
            $this->error('SQL error: ' . $result['error'], $this->console($key, 'sql'));
        }
        $this->success(
            'Statement executed in ' . ($result['duration_ms'] ?? 0) . ' ms'
            . (($result['affected'] ?? 0) > 0 ? ' · ' . (int) $result['affected'] . ' row(s) affected' : '') . '.',
            $this->console($key, 'sql')
        );
    }

    /* ---------------------------------------------------------------------
     * Demonstration data
     * ------------------------------------------------------------------ */

    public function demoData(string $key): void
    {
        $this->guard($key);
        $this->view('developer/demo', [
            'pageTitle' => 'Demonstration data',
            'developerKey' => $key,
            'counts' => $this->demoCounts(),
            'demoMode' => Setting::demoMode(),
            'hasDemoAccounts' => (int) Database::scalar("SELECT COUNT(*) FROM users WHERE username = 'demo.dean'", [], 0) > 0,
        ], 'layouts/developer');
    }

    public function generateDemo(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        try {
            $stats = (new DemoService())->seed();
        } catch (\Throwable $e) {
            $this->backWithError('Demo data could not be generated: ' . $e->getMessage(), $this->console($key, 'demo'));
        }
        Setting::clearCache();
        (new AuditService())->record('developer.demo_generate', 'demo', null, 'Generated synthetic demonstration data');
        $this->success(
            'Synthetic demonstration data generated: ' . (int) ($stats['responses'] ?? 0) . ' responses across '
            . (int) ($stats['sessions'] ?? 0) . ' sessions. Demo mode is now ON. Password for demo accounts: Demo@12345.',
            $this->console($key, 'demo')
        );
    }

    public function resetDemo(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        try {
            (new DemoService())->reset();
            Setting::set('demo_mode', '0', 'demo');
            Setting::clearCache();
        } catch (\Throwable $e) {
            $this->backWithError('Demo data could not be reset: ' . $e->getMessage(), $this->console($key, 'demo'));
        }
        (new AuditService())->record('developer.demo_reset', 'demo', null, 'Removed synthetic demonstration data');
        $this->success('All flagged demonstration data was removed. Live records were not touched. Demo mode is OFF.', $this->console($key, 'demo'));
    }

    /* ---------------------------------------------------------------------
     * Helpers
     * ------------------------------------------------------------------ */

    private function guard(string $key): void
    {
        header('X-Robots-Tag: noindex, nofollow, noarchive');
        header('Referrer-Policy: no-referrer');
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');

        $configured = trim((string) config('app.developer_key', ''));
        if ($configured === '' || $key === '' || !hash_equals($configured, $key)) {
            abort(404);
        }
    }

    private function console(string $key, string $path = ''): string
    {
        $base = 'developer/' . rawurlencode($key);
        return $path === '' ? $base : $base . '/' . ltrim($path, '/');
    }

    private function healthChecks(string $key): array
    {
        $storage = BASE_PATH . '/storage';
        $local = BASE_PATH . '/config/local.php';
        return [
            ['label' => 'Storage directory writable', 'ok' => is_dir($storage) && is_writable($storage), 'detail' => $storage],
            ['label' => 'config/local.php writable', 'ok' => is_file($local) && is_writable($local), 'detail' => $local],
            ['label' => 'Developer key configured', 'ok' => strlen(trim((string) config('app.developer_key', ''))) >= 32, 'detail' => strlen((string) config('app.developer_key', '')) . ' characters'],
            ['label' => 'HTTPS', 'ok' => Request::isSecure(), 'detail' => Request::isSecure() ? 'Secure request' : 'Plain HTTP (local development only)'],
            ['label' => 'Debug mode off', 'ok' => !config('app.debug', false), 'detail' => config('app.debug', false) ? 'Debug is ON' : 'Debug is off'],
            ['label' => 'Developer URL is unlinked', 'ok' => true, 'detail' => 'No navigation entry points to this console'],
        ];
    }

    private function userRoleCounts(): array
    {
        $rows = Database::fetchAll(
            'SELECT r.slug, r.name,
                    COUNT(u.id) AS total,
                    SUM(CASE WHEN u.is_demo = 1 THEN 1 ELSE 0 END) AS demo_count,
                    SUM(CASE WHEN u.is_demo = 0 THEN 1 ELSE 0 END) AS live_count
             FROM roles r LEFT JOIN users u ON u.role_id = r.id
             GROUP BY r.id, r.slug, r.name ORDER BY r.id ASC'
        );
        $out = [];
        foreach ($rows as $row) {
            $out[(string) $row['slug']] = [
                'name' => (string) $row['name'],
                'total' => (int) $row['total'],
                'demo' => (int) $row['demo_count'],
                'live' => (int) $row['live_count'],
            ];
        }
        return $out;
    }

    private function userFormData(?array $user): array
    {
        return [
            'pageTitle' => $user ? 'Edit user · ' . $user['username'] : 'New user',
            'user' => $user,
            'roles' => Database::fetchAll('SELECT id, slug, name FROM roles ORDER BY id'),
            'departments' => Database::fetchAll('SELECT id, code, name FROM departments ORDER BY code'),
            'programs' => Database::fetchAll('SELECT id, code, name FROM programs ORDER BY code'),
            'sections' => Database::fetchAll('SELECT id, code, name FROM sections ORDER BY code'),
            'demoMode' => Setting::demoMode(),
            'activeDeans' => $this->activeDeans(),
        ];
    }

    private function userPayload(): array
    {
        return [
            'first_name' => $this->postString('first_name'),
            'middle_name' => $this->postString('middle_name'),
            'last_name' => $this->postString('last_name'),
            'suffix' => $this->postString('suffix'),
            'username' => strtolower($this->postString('username')),
            'email' => strtolower($this->postString('email')),
            'employee_number' => $this->postString('employee_number'),
            'student_number' => $this->postString('student_number'),
            'phone' => $this->postString('phone'),
            'role' => $this->postString('role'),
            'status' => $this->postString('status', 'active'),
        ];
    }

    private function rememberUserInput(array $payload): void
    {
        Session::set('_old', $payload);
    }

    private function userValueExists(string $column, string $value, ?int $ignoreId = null): bool
    {
        if ($value === '' || !in_array($column, ['username', 'email', 'employee_number', 'student_number'], true)) {
            return false;
        }
        $sql = 'SELECT COUNT(*) FROM users WHERE ' . $column . ' = ?';
        $params = [$value];
        if ($ignoreId !== null) {
            $sql .= ' AND id <> ?';
            $params[] = $ignoreId;
        }
        return (int) Database::scalar($sql, $params, 0) > 0;
    }

    private function activeDeans(): int
    {
        return (int) Database::scalar(
            "SELECT COUNT(*) FROM users u JOIN roles r ON r.id = u.role_id WHERE r.slug = 'dean' AND u.status = 'active'",
            [],
            0
        );
    }

    private function foreignOptions(string $table): array
    {
        $options = [];
        foreach ($this->data->columns($table) as $column) {
            if (($column['input_type'] ?? '') === 'foreign') {
                $options[$column['name']] = $this->data->lookupOptions($column);
            }
        }
        return $options;
    }

    private function demoCounts(): array
    {
        $scope = Setting::demoMode() ? 1 : 0;
        return [
            'departments' => (int) Database::scalar('SELECT COUNT(*) FROM departments WHERE is_demo = ?', [$scope], 0),
            'programs' => (int) Database::scalar('SELECT COUNT(*) FROM programs WHERE is_demo = ?', [$scope], 0),
            'courses' => (int) Database::scalar('SELECT COUNT(*) FROM courses WHERE is_demo = ?', [$scope], 0),
            'sections' => (int) Database::scalar('SELECT COUNT(*) FROM sections WHERE is_demo = ?', [$scope], 0),
            'users' => (int) Database::scalar('SELECT COUNT(*) FROM users WHERE is_demo = ?', [$scope], 0),
            'surveys' => (int) Database::scalar('SELECT COUNT(*) FROM surveys WHERE is_demo = ?', [$scope], 0),
            'sessions' => (int) Database::scalar('SELECT COUNT(*) FROM evaluation_sessions WHERE is_demo = ?', [$scope], 0),
            'responses' => (int) Database::scalar(
                'SELECT COUNT(*) FROM evaluation_responses r JOIN evaluation_sessions es ON es.id = r.evaluation_session_id WHERE es.is_demo = ?',
                [$scope],
                0
            ),
            'observations' => (int) Database::scalar('SELECT COUNT(*) FROM class_observations WHERE is_demo = ?', [$scope], 0),
            'uat_surveys' => (int) Database::scalar('SELECT COUNT(*) FROM uat_surveys WHERE is_demo = ?', [$scope], 0),
        ];
    }
}
